def count_divisors(n):
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

results = []
for k in range(1, 16):
    N = 2 * (k**3)
    d_N = count_divisors(N)
    RHS = 2 * k
    results.append((k, N, d_N, RHS))

print("k, 2k^3, d(2k^3), 2k")
for k, N, d_N, RHS in results:
    print(f"{k}, {N}, {d_N}, {RHS}")

